class Fogata:
    def encender(self):
        return "Fuego encendido"
mi_fuego = Fogata()
mi_fuego.encender()

class Tienda:
    def __init__(self, tela, piedras):
        self.tela = tela
        self.piedras = piedras
    def armar(self):
        return "Tienda armada"
mi_tienda = Tienda(5, 4)
mi_tienda.armar()

class Fogata:
    def encender(self):
        return "Fuego encendido"
class Tienda:
    def armar(self):
        return "Tienda armada"
class Campamento:
    def __init__(self, fogata, tienda):
        self.fogata = fogata
        self.tienda = tienda
    def armar(self):
        return self.fogata.encender() + " y " + self.tienda.armar()
mi_fuego = Fogata()
mi_tienda = Tienda()
campo = Campamento(mi_fuego, mi_tienda)
campo.armar()

